    34	  # Never tear the fixtures down under a live command: stop it first, then wait for it to exit.
    35	  if [[ $child -ne 0 ]] && kill -0 "$child" 2>/dev/null; then
    36	    kill -TERM -- "-$child" 2>/dev/null || kill -TERM "$child" 2>/dev/null || true
    37	    wait "$child" 2>/dev/null || true
    38	  fi
